import React, { useState, useEffect } from 'react';
import { CheckCircle2, AlertCircle, Server, Database, Activity, Clock, RefreshCw } from 'lucide-react';

const SystemStatusContent = () => {
    const [status, setStatus] = useState<{
        status: 'operational' | 'degraded' | 'down';
        checks?: {
            database: { status: string; latency: string };
            payments: { last_webhook: string; last_transaction: string };
        };
        timestamp?: string;
    } | null>(null);
    const [loading, setLoading] = useState(true);
    const [lastChecked, setLastChecked] = useState<Date | null>(null);

    const checkStatus = async () => {
        setLoading(true);
        try {
            const res = await fetch('/api/system-status');
            const data = await res.json();
            setStatus(data);
            setLastChecked(new Date());
        } catch (err) {
            setStatus({ status: 'down' });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        checkStatus();
        const interval = setInterval(checkStatus, 30000); // Check every 30s
        return () => clearInterval(interval);
    }, []);

    const isOperational = status?.status === 'operational';

    return (
        <div className="space-y-8 animate-fade-in max-w-4xl mx-auto">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900">System Status</h1>
                    <p className="text-slate-500 text-sm mt-1">Real-time monitoring of infrastructure and services.</p>
                </div>
                <button
                    onClick={checkStatus}
                    disabled={loading}
                    className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-50 transition-all disabled:opacity-50"
                >
                    <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
                    Refresh
                </button>
            </div>

            {/* Main Status Card */}
            <div className={`p-8 rounded-3xl border ${isOperational ? 'bg-emerald-50/50 border-emerald-100' : 'bg-rose-50/50 border-rose-100'} transition-all`}>
                <div className="flex items-center gap-4">
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center ${isOperational ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                        {isOperational ? <CheckCircle2 size={32} /> : <AlertCircle size={32} />}
                    </div>
                    <div>
                        <h2 className={`text-2xl font-bold ${isOperational ? 'text-emerald-900' : 'text-rose-900'}`}>
                            {isOperational ? 'All Systems Operational' : 'System Issues Detected'}
                        </h2>
                        <p className={`${isOperational ? 'text-emerald-700' : 'text-rose-700'} mt-1`}>
                            {isOperational
                                ? 'All services are running normally. No incidents reported.'
                                : 'Some services are experiencing disruptions. Check details below.'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Database Status */}
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="p-2 bg-blue-50 rounded-lg text-blue-600">
                            <Database size={20} />
                        </div>
                        <h3 className="font-bold text-slate-900">Database</h3>
                        <span className={`ml-auto px-2.5 py-0.5 rounded-full text-xs font-bold uppercase ${status?.checks?.database.status === 'connected' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                            {status?.checks?.database.status || 'Unknown'}
                        </span>
                    </div>

                    <div className="space-y-4">
                        <div className="flex justify-between items-center py-3 border-b border-slate-50">
                            <span className="text-sm text-slate-500">Connection Latency</span>
                            <span className="font-mono font-bold text-slate-900">{status?.checks?.database.latency || '---'}</span>
                        </div>
                        <div className="flex justify-between items-center py-3 border-b border-slate-50">
                            <span className="text-sm text-slate-500">Region</span>
                            <span className="font-medium text-slate-900">ap-south-1 (Mumbai)</span>
                        </div>
                        <div className="flex justify-between items-center pt-2">
                            <span className="text-sm text-slate-500">Status</span>
                            <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600">
                                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                                Healthy
                            </span>
                        </div>
                    </div>
                </div>

                {/* Payment Gateway Status */}
                <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all">
                    <div className="flex items-center gap-3 mb-6">
                        <div className="p-2 bg-purple-50 rounded-lg text-purple-600">
                            <Server size={20} />
                        </div>
                        <h3 className="font-bold text-slate-900">Payment Gateway</h3>
                        <span className="ml-auto px-2.5 py-0.5 rounded-full text-xs font-bold uppercase bg-emerald-50 text-emerald-600">
                            Active
                        </span>
                    </div>

                    <div className="space-y-4">
                        <div className="flex justify-between items-center py-3 border-b border-slate-50">
                            <span className="text-sm text-slate-500">Last Webhook Received</span>
                            <span className="text-sm font-medium text-slate-900">
                                {status?.checks?.payments.last_webhook ? new Date(status.checks.payments.last_webhook).toLocaleString() : 'Never'}
                            </span>
                        </div>
                        <div className="flex justify-between items-center py-3 border-b border-slate-50">
                            <span className="text-sm text-slate-500">Last Transaction</span>
                            <span className="text-sm font-medium text-slate-900">
                                {status?.checks?.payments.last_transaction ? new Date(status.checks.payments.last_transaction).toLocaleString() : 'Never'}
                            </span>
                        </div>
                        <div className="flex justify-between items-center pt-2">
                            <span className="text-sm text-slate-500">Uptime</span>
                            <span className="flex items-center gap-1.5 text-xs font-bold text-emerald-600">
                                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                                99.9%
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="text-center text-xs text-slate-400 mt-8">
                Last updated: {lastChecked ? lastChecked.toLocaleString() : 'Never'}
            </div>
        </div>
    );
};

export default SystemStatusContent;
